P2A-DEV-CD03:
NUMBER n.
INPUT(n).
IF (n > 0) {
 IF (n % 2 == 0) {
  DISPLAYNL("POSITIVE EVEN").
 } ELSE {
  DISPLAYNL("POSITIVE ODD").
 }
} ELSE {
 DISPLAYNL("NONPOSITIVE").
}

P2A-DEV-CD04:
NUMBER n.
INPUT(n).
IF (n % 3 == 0 AND n % 5 == 0) {
 DISPLAYNL("BOTH").
} ELSEIF (n % 3 == 0) {
 DISPLAYNL("THREE").
} ELSEIF (n % 5 == 0) {
 DISPLAYNL("FIVE").
} ELSE {
 DISPLAYNL("NEITHER").
}

P2A-DEV-CD06:
NUMBER n.
INPUT(n).
IF (n % 2 == 0) { IF (n < 20) { DISPLAYNL("EVEN-SMALL"). } ELSE { DISPLAYNL("EVEN-LARGE"). } } ELSE { IF (n < 20) { DISPLAYNL("ODD-SMALL"). } ELSE { DISPLAYNL("ODD-LARGE"). } }

P2A-DEV-CD07:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] parts = strings.SPLIT(line, "|").
NUMBER a = strings.TO_NUMBER(parts[0]).
NUMBER b = strings.TO_NUMBER(parts[1]).
IMPORT math.
NUMBER aa = math.ABS(a).
NUMBER bb = math.ABS(b).
IF (aa > bb) {
 DISPLAYNL("A").
} ELSEIF (bb > aa) {
 DISPLAYNL("B").
} ELSE {
 DISPLAYNL("TIE").
}

